<template>
 <view v-if="sample" class="display-example" :data-example-module="module" :aria-label="sample.label+'展示模板'">
  <view class="example-heading"><view><text class="example-tag">展示示例</text><text class="example-label">{{sample.label}}模板</text></view><button v-if="!empty" role="button" class="text-btn" @click="opened=!opened;details=false">{{opened?'收起模板示例':'查看模板示例'}}</button></view>
  <text class="example-note">仅用于确认页面效果；操作不提交，也不计入实际记录。</text>
  <template v-if="empty||opened">
   <view v-if="!details" class="example-card"><view class="example-art"><image :src="'/static/icons/'+sample.icon+'.png'" mode="aspectFit"/><text>{{sample.label}}</text></view><view class="example-body"><text class="example-title">{{sample.title}}</text><text class="example-summary">{{sample.summary}}</text><view class="example-fields"><text v-for="pair in sample.fields.slice(0,3)" :key="pair[0]"><text class="example-key">{{pair[0]}}：</text>{{pair[1]}}</text></view><button role="button" class="btn secondary" @click="details=true">查看{{sample.label}}详情示例 →</button></view></view>
   <view v-else class="example-document"><button role="button" class="text-btn" @click="details=false;formOpen=false;result=false">‹ 返回模板概览</button><text class="example-title">{{sample.title}}</text><text class="example-summary">{{sample.summary}}</text><view class="example-fields"><text v-for="pair in sample.fields" :key="pair[0]"><text class="example-key">{{pair[0]}}：</text>{{pair[1]}}</text></view><view v-for="section in sample.sections" :key="section[0]" class="example-section"><text class="example-section-title">{{section[0]}}</text><text>{{section[1]}}</text></view><view class="example-section"><text class="example-section-title">流程示例</text><view v-for="(step,index) in sample.steps" :key="step" class="example-step"><text>{{index+1}}</text><text>{{step}}</text></view></view>
    <button v-if="module==='labs'&&!formOpen" role="button" class="btn" @click="formOpen=true">演示填写预约（不提交）</button>
    <view v-if="formOpen" class="example-form"><text class="example-section-title">预约填写演示</text><text class="example-note">这里只演示表单，没有占用名额，也不会创建预约。</text><view class="time-fields"><view class="field-group"><text>预约日期</text><DateTimeField v-model="date" mode="date"/></view><view class="field-group"><text>预约时段</text><ChoiceField v-model="slot" :options="[{value:'AM',label:'上午08:00—12:00'},{value:'PM',label:'下午14:00—18:00'}]"/></view></view><view class="field-group"><text>指导老师姓名</text><input v-model="teacher" class="field" placeholder="例如：示例老师" maxlength="80"/></view><view class="field-group"><text>预约用途</text><textarea v-model="purpose" class="field textarea" placeholder="填写本次实验或项目用途" maxlength="500"/></view><view class="example-fields"><text>本人：示例同学（自动计入示意）</text><text>同行人员：示例成员（外院标记示意）</text></view><text v-if="error" class="example-error" role="alert">{{error}}</text><button role="button" class="btn secondary" @click="preview">查看演示结果</button><view v-if="result" class="example-result" role="status"><text class="example-section-title">演示状态：待老师审批</text><text>{{date}} · {{slot==='AM'?'上午':'下午'}} · {{teacher}}</text><text>这只是展示结果，没有生成真实预约。正式使用请从实际实验室条目申请。</text></view></view>
   </view>
  </template>
 </view>
</template>
<script setup>
import {computed,ref} from 'vue';import {presentationExamples} from '../services/presentation-examples.mjs';import DateTimeField from './DateTimeField.vue';import ChoiceField from './ChoiceField.vue';
const props=defineProps({module:String,empty:Boolean});const sample=computed(()=>presentationExamples[props.module]);
const opened=ref(false),details=ref(false),formOpen=ref(false),result=ref(false),error=ref(''),teacher=ref(''),purpose=ref('');
const date=ref(new Date(Date.now()+8*3600000+86400000).toISOString().slice(0,10)),slot=ref('AM');
function preview(){error.value='';result.value=false;if(!teacher.value.trim()||!purpose.value.trim()){error.value='请填写指导老师姓名和预约用途后查看演示结果';return;}result.value=true;}
</script>
